//
//  AirlineCatalog.swift
//  WhatTheFlight
//
//  ICAO airline designators → display names. ~5,800 operators come from OpenFlights
//  (`AirlineCatalog+Data.swift`, regenerated by Scripts/generate_catalogs.py); the
//  hand-curated list below wins wherever the two disagree, so tidy names belong here.
//

import Foundation

struct Airline: Hashable, Sendable {
    let icao: String
    let iata: String?
    let name: String
    /// Radio telephony callsign ("SPEEDBIRD" for British Airways), when known.
    var radioCallsign: String? = nil
    var country: String? = nil
}

enum AirlineCatalog {
    /// Resolves the operator from the feed's airline field, falling back to the callsign prefix.
    static func airline(icao: String?, callsign: String?, flightNumber: String?) -> Airline? {
        if let icao = icao?.uppercased(), let hit = byICAO[icao] { return hit }
        // Special words first: "SAM44" is a US Air Force VIP flight, whatever else holds "SAM".
        if let word = leadingLetters(of: callsign), let hit = special[word] { return hit }
        if let prefix = icaoPrefix(ofCallsign: callsign), let hit = byICAO[prefix] { return hit }
        if callsign == nil, let number = flightNumber?.uppercased(), number.count > 2 {
            let prefix = String(number.prefix(2))
            if number.dropFirst(2).first?.isNumber == true, let hit = curatedByIATA[prefix] { return hit }
        }
        return nil
    }

    static func airline(icao: String) -> Airline? { byICAO[icao.uppercased()] }

    /// "DAL1032" → "DAL". ICAO flight callsigns are three letters followed by the flight
    /// number, so "LIFE2" or "N5404T" never match by accident.
    static func icaoPrefix(ofCallsign callsign: String?) -> String? {
        guard let callsign = callsign?.uppercased(), callsign.count > 3 else { return nil }
        let chars = Array(callsign)
        guard chars[0...2].allSatisfy({ $0.isASCII && $0.isLetter }), chars[3].isNumber else { return nil }
        return String(chars[0...2])
    }

    private static func leadingLetters(of callsign: String?) -> String? {
        guard let callsign = callsign?.uppercased() else { return nil }
        let letters = String(callsign.prefix { $0.isASCII && $0.isLetter })
        return letters.isEmpty ? nil : letters
    }

    private static let byICAO: [String: Airline] = {
        var table: [String: Airline] = [:]
        for line in generatedRaw.split(separator: "\n") {
            let p = line.split(separator: "|", omittingEmptySubsequences: false).map(String.init)
            guard p.count == 5 else { continue }
            table[p[0]] = Airline(icao: p[0], iata: p[1].nilIfEmpty, name: p[2], radioCallsign: p[3].nilIfEmpty, country: p[4].nilIfEmpty)
        }
        for airline in curated {
            let generated = table[airline.icao]
            table[airline.icao] = Airline(
                icao: airline.icao,
                iata: airline.iata ?? generated?.iata,
                name: airline.name,
                radioCallsign: airline.radioCallsign ?? generated?.radioCallsign,
                country: airline.country ?? generated?.country
            )
        }
        return table
    }()

    private static let curated: [Airline] = raw.split(separator: "\n").compactMap { line in
        let p = line.trimmingCharacters(in: .whitespaces).split(separator: "|", omittingEmptySubsequences: false).map(String.init)
        guard p.count >= 3 else { return nil }
        return Airline(icao: p[0], iata: p[1].nilIfEmpty, name: p[2], radioCallsign: p.count > 3 ? p[3].nilIfEmpty : nil)
    }

    private static let curatedByIATA: [String: Airline] = {
        var table: [String: Airline] = [:]
        for airline in curated { if let iata = airline.iata, table[iata] == nil { table[iata] = byICAO[airline.icao] } }
        return table
    }()

    /// Callsigns that aren't ICAO airline designators: military, government and air
    /// ambulance words, matched against the callsign's leading letters ("SAM44", "LIFE2").
    private static let special: [String: Airline] = {
        let rows: [(String, String)] = [
            ("SAM", "US Air Force · Special Air Mission"),
            ("NAVY", "US Navy"),
            ("ARMY", "US Army"),
            ("MARINE", "US Marine Corps"),
            ("LIFE", "Air ambulance"),
            ("LIFEGUARD", "Air ambulance"),
            ("MEDEVAC", "Air ambulance"),
            ("MEDIC", "Air ambulance"),
            ("ANGEL", "Air ambulance"),
            ("MERCY", "Air ambulance"),
            ("CAREFLITE", "Air ambulance"),
            ("POLICE", "Police"),
            ("SHERIFF", "Sheriff"),
            ("TROOPER", "State police"),
            ("COPTER", "Helicopter"),
            ("NASA", "NASA"),
        ]
        var table: [String: Airline] = [:]
        for (word, name) in rows { table[word] = Airline(icao: word, iata: nil, name: name) }
        return table
    }()

    /// Words in `special` that denote an air ambulance (used to flag medical traffic).
    static let medicalWords: Set<String> = ["LIFE", "LIFEGUARD", "MEDEVAC", "MEDIC", "ANGEL", "MERCY", "CAREFLITE"]
    /// Words and ICAO designators for military operators.
    static let militaryDesignators: Set<String> = [
        "SAM", "NAVY", "ARMY", "MARINE",
        "RCH", "CNV", "PAT", "CGX", "RRR", "RFR", "GAF", "IAM", "CFC", "BAF", "NAF", "HAF", "SUI", "PLF", "ASY", "CTM",
    ]
    /// Government (non-military) operators.
    static let governmentDesignators: Set<String> = ["NASA", "CBP", "POLICE", "SHERIFF", "TROOPER"]

